/**
 * Exercises production WAL open/recovery with substantially more record data than the child JVM can retain in heap. The
 * fixtures are streamed directly to disk so the probe isolates reading/recovery from the asynchronous writer.
 */
class ValueStoreWalBoundedMemoryTest {

	private static final int RECORD_COUNT = Integer.getInteger("rdf4j.wal.test.records", 200_000);
	private static final int OVERSIZED_FRAME_BYTES = 64 * 1024 * 1024;
	private static final String LABEL_PREFIX = "value-" + "a".repeat(120);
	private static final String HEADER = "{\"t\":\"V\",\"ver\":1,\"store\":\"bounded-memory-test\","
			+ "\"engine\":\"valuestore\",\"created\":0,\"segment\":1,\"firstId\":1}\n";

	@TempDir
	Path tempDir;

	@Test
	void reopensExistingStoreWithWalLargerThanHeap() throws Exception {
		runInConstrainedHeap("reopen");
	}

	@Test
	void recoversMissingValueFilesWithWalLargerThanHeap() throws Exception {
		runInConstrainedHeap("recover");
	}

	@Test
	void bootstrapRejectsValueLargerThanItsReadBudgetWithoutHeapExhaustion() throws Exception {
		runInConstrainedHeap("bootstrap-large-record");
	}

	@Test
	void bootstrapBoundsReferencedNamespacesWithoutHeapExhaustion() throws Exception {
		runInConstrainedHeap("bootstrap-large-namespace");
	}

	@Test
	void requiredRecoveryFailsCleanlyWhenOneRecordExceedsReadBudget() throws Exception {
		runInConstrainedHeap("recover-large-record");
	}

	@Test
	void rejectsTruncatedUncompressedFrameWithoutAllocatingItsClaimedLength() throws Exception {
		runInConstrainedHeap("truncated-frame");
	}

	@Test
	void rejectsCompressedFrameLargerThanHeapWithoutMaterializingIt() throws Exception {
		runInConstrainedHeap("compressed-frame");
	}

	@Test
	void sparseMaximumIdDoesNotAllocateAnIdSizedHeapStructure() throws Exception {
		runInConstrainedHeap("sparse-id");
	}

	private void runInConstrainedHeap(String probe) throws Exception {
		String classpath = System.getProperty("surefire.test.class.path");
		if (classpath == null || classpath.isBlank()) {
			classpath = System.getProperty("java.class.path");
		}
		Path output = tempDir.resolve(probe + ".log");
		String java = Path.of(System.getProperty("java.home"), "bin", "java").toString();
		Process process = new ProcessBuilder(java, "-Xmx32m", "-XX:+ExitOnOutOfMemoryError", "-ea", "-cp", classpath,
				ValueStoreWalBoundedMemoryTest.class.getName(), probe, tempDir.toString())
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		boolean exited;
		try {
			exited = process.waitFor(120, TimeUnit.SECONDS);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				process.waitFor(10, TimeUnit.SECONDS);
			}
		}
		String log = Files.readString(output);
		assertThat(exited).withFailMessage("Constrained-heap WAL probe timed out:%n%s", log).isTrue();
		assertThat(process.exitValue()).withFailMessage("Constrained-heap WAL probe failed:%n%s", log).isZero();
		assertThat(log).contains("WAL_MEMORY_PROBE_PASSED=" + probe);
	}

	public static void main(String[] args) throws Exception {
		String probe = args[0];
		Path directory = Path.of(args[1]);
		if (Runtime.getRuntime().maxMemory() > 32L * 1024 * 1024) {
			throw new AssertionError("The WAL probe must run with a 32 MiB maximum heap");
		}
		switch (probe) {
		case "reopen":
			runStoreProbe(directory, false);
			break;
		case "recover":
			runStoreProbe(directory, true);
			break;
		case "bootstrap-large-record":
			runBootstrapReadLimitProbe(directory, false);
			break;
		case "bootstrap-large-namespace":
			runBootstrapReadLimitProbe(directory, true);
			break;
		case "recover-large-record":
			runRecoveryReadLimitProbe(directory);
			break;
		case "truncated-frame":
			runCorruptFrameProbe(directory, false);
			break;
		case "compressed-frame":
			runCorruptFrameProbe(directory, true);
			break;
		case "sparse-id":
			runSparseIdProbe(directory);
			break;
		default:
			throw new IllegalArgumentException("Unknown WAL memory probe: " + probe);
		}
		System.out.println("WAL_MEMORY_PROBE_PASSED=" + probe);
	}

	private static void runBootstrapReadLimitProbe(Path directory, boolean namespaceReference) throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		try (ValueStore store = new ValueStore(values.toFile())) {
			if (namespaceReference) {
				store.storeValue(SimpleValueFactory.getInstance().createIRI("urn:bootstrap:local"));
			} else {
				store.storeValue(SimpleValueFactory.getInstance().createBNode("before-upgrade"));
			}
			store.sync();
		}
		// Write a genuine large encoded value in bounded chunks, without requiring the fixture to fit in heap.
		try (RandomAccessFile ids = new RandomAccessFile(values.resolve("values.id").toFile(), "rw");
				RandomAccessFile data = new RandomAccessFile(values.resolve("values.dat").toFile(), "rw")) {
			ids.seek(Long.BYTES);
			long offset = ids.readLong();
			if (namespaceReference) {
				// Preserve the tiny IRI record, but redirect its namespace ID to a large appended value.
				offset = data.length();
				ids.seek(Long.BYTES);
				ids.writeLong(offset);
			}
			int length = 20 * 1024 * 1024;
			data.seek(offset);
			data.writeInt(length);
			data.writeByte(namespaceReference ? 'a' : 2); // A namespace or NativeStore BNODE_VALUE
			byte[] block = new byte[8192];
			Arrays.fill(block, (byte) 'a');
			for (int remaining = length - 1; remaining > 0;) {
				int chunk = Math.min(remaining, block.length);
				data.write(block, 0, chunk);
				remaining -= chunk;
			}
		}
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(directory.resolve("wal"))
				.storeUuid("bounded-memory-test")
				.syncBootstrapOnOpen(true)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = new ValueStore(values.toFile(), false, 16, 16, 16, 16, wal)) {
			// A single oversized value must be reported and skipped without killing the JVM or WAL writer.
			wal.logMint(3, ValueStoreWalValueKind.BNODE, "after-bootstrap", "", "", 0);
		}
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			ValueStoreWalReader.Summary summary = reader.summarize();
			if (!summary.complete() || summary.maxId() != 3) {
				throw new AssertionError("WAL writer did not remain usable after rejecting a bootstrap value");
			}
		}
	}

	private static void runRecoveryReadLimitProbe(Path directory) throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		try (ValueStore store = new ValueStore(values.toFile())) {
			store.storeValue(SimpleValueFactory.getInstance().createBNode("existing"));
			store.sync();
		}
		Path walDirectory = Files.createDirectories(directory.resolve("wal"));
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(walDirectory.resolve("wal-1.v1")))) {
			writeFrame(output, HEADER);
			writeFrame(output, "{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"B\",\"lex\":\"existing\"}\n");
			writeFrame(output, "{\"t\":\"M\",\"lsn\":2,\"id\":2,\"vk\":\"B\",\"lex\":\""
					+ "a".repeat(2 * 1024 * 1024) + "\"}\n");
		}
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("bounded-memory-test")
				.recoverValueStoreOnOpen(true)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			try (ValueStore ignored = new ValueStore(values.toFile(), false, 16, 16, 16, 16, wal)) {
				throw new AssertionError("Required recovery must fail instead of opening an incomplete value store");
			} catch (IOException expected) {
				if (!expected.getMessage().contains("bounded read limits")) {
					throw expected;
				}
			}
		}
		try (ValueStore store = new ValueStore(values.toFile())) {
			if (!"existing".equals(store.getValue(1).stringValue())
					|| store.storeValue(SimpleValueFactory.getInstance().createBNode("second")) != 2) {
				throw new AssertionError("A failed pre-clear replay must preserve the original values");
			}
		}
		try (var files = Files.list(values)) {
			if (files.anyMatch(path -> path.getFileName().toString().startsWith("wal-recovery-"))) {
				throw new AssertionError("Failed recovery leaked temporary spool files");
			}
		}
	}

	private static void runSparseIdProbe(Path directory) throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		try (ValueStore store = new ValueStore(values.toFile())) {
			store.storeValue(SimpleValueFactory.getInstance().createBNode("existing"));
			store.sync();
		}
		Path walDirectory = Files.createDirectories(directory.resolve("wal"));
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(walDirectory.resolve("wal-1.v1")))) {
			writeFrame(output, HEADER);
			writeFrame(output, "{\"t\":\"M\",\"lsn\":1,\"id\":1,\"vk\":\"B\",\"lex\":\"existing\"}\n");
			writeFrame(output, "{\"t\":\"M\",\"lsn\":2,\"id\":" + Integer.MAX_VALUE
					+ ",\"vk\":\"B\",\"lex\":\"after-gap\"}\n");
		}
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("bounded-memory-test")
				.recoverValueStoreOnOpen(true)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = new ValueStore(values.toFile(), false, ValueStore.VALUE_CACHE_SIZE,
						ValueStore.VALUE_ID_CACHE_SIZE, ValueStore.NAMESPACE_CACHE_SIZE,
						ValueStore.NAMESPACE_ID_CACHE_SIZE, wal)) {
			if (!"existing".equals(store.getValue(1).stringValue())
					|| store.storeValue(SimpleValueFactory.getInstance().createBNode("second")) != 2) {
				throw new AssertionError("Recovery with gapped IDs must preserve the existing ValueStore");
			}
		}
	}

	private static void runStoreProbe(Path directory, boolean recover) throws Exception {
		Path values = Files.createDirectories(directory.resolve("values"));
		Path walDirectory = Files.createDirectories(directory.resolve("wal"));
		Path segment = walDirectory.resolve("wal-1.v1");
		try (OutputStream output = new BufferedOutputStream(Files.newOutputStream(segment));
				ValueStore store = new ValueStore(values.toFile())) {
			writeFrame(output, HEADER);
			for (int id = 1; id <= RECORD_COUNT; id++) {
				String label = label(id);
				if (!recover) {
					int assigned = store.storeValue(SimpleValueFactory.getInstance().createBNode(label));
					if (assigned != id) {
						throw new AssertionError("Fixture assigned " + assigned + " instead of " + id);
					}
				}
				writeFrame(output, "{\"t\":\"M\",\"lsn\":" + id + ",\"id\":" + id
						+ ",\"vk\":\"B\",\"lex\":\"" + label + "\",\"dt\":\"\",\"lang\":\"\",\"hash\":0}\n");
			}
			store.sync();
		}
		if (recover) {
			Files.delete(values.resolve("values.dat"));
			Files.delete(values.resolve("values.id"));
			Files.delete(values.resolve("values.hash"));
		}
		if (Files.size(segment) <= Runtime.getRuntime().maxMemory()) {
			throw new AssertionError("The WAL fixture must be larger than the child JVM heap");
		}
		System.out.println("WAL_FIXTURE_READY records=" + RECORD_COUNT + " bytes=" + Files.size(segment));
		System.gc();
		long openStarted = System.nanoTime();
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("bounded-memory-test")
				.recoverValueStoreOnOpen(recover)
				.build();
		try (ValueStoreWAL wal = ValueStoreWAL.open(config);
				ValueStore store = new ValueStore(values.toFile(), false, ValueStore.VALUE_CACHE_SIZE,
						ValueStore.VALUE_ID_CACHE_SIZE, ValueStore.NAMESPACE_CACHE_SIZE,
						ValueStore.NAMESPACE_ID_CACHE_SIZE, wal)) {
			long openNanos = System.nanoTime() - openStarted;
			System.gc();
			long heapUsed = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
			System.out.println("WAL_PROBE_METRICS records=" + RECORD_COUNT + " recovery=" + recover
					+ " walBytes=" + Files.size(segment) + " openNanos=" + openNanos + " heapAfterGc=" + heapUsed
					+ " maxHeap=" + Runtime.getRuntime().maxMemory());
			for (int id : new int[] { 1, RECORD_COUNT / 2, RECORD_COUNT }) {
				if (!label(id).equals(store.getValue(id).stringValue())
						|| store.getID(SimpleValueFactory.getInstance().createBNode(label(id))) != id) {
					throw new AssertionError("WAL open/recovery did not preserve value ID " + id);
				}
			}
			long nextLsn = wal.logMint(RECORD_COUNT + 1, ValueStoreWalValueKind.BNODE, "after-open", "", "", 0);
			if (nextLsn <= RECORD_COUNT) {
				throw new AssertionError("WAL open reused an existing LSN: " + nextLsn);
			}
		}
	}

	private static void runCorruptFrameProbe(Path directory, boolean compressed) throws Exception {
		Path walDirectory = Files.createDirectories(directory.resolve("wal"));
		Path segment = walDirectory.resolve(compressed ? "wal-1.v1.gz" : "wal-1.v1");
		try (OutputStream file = new BufferedOutputStream(Files.newOutputStream(segment));
				OutputStream output = compressed ? new GZIPOutputStream(file) : file) {
			writeFrame(output, HEADER);
			writeIntLE(output, OVERSIZED_FRAME_BYTES);
			if (compressed) {
				// A small gzip file can expand to a frame larger than the available heap. Its CRC is deliberately bad.
				byte[] zeros = new byte[8192];
				for (int written = 0; written < OVERSIZED_FRAME_BYTES; written += zeros.length) {
					output.write(zeros);
				}
				writeIntLE(output, 0);
			}
		}
		ValueStoreWalConfig config = ValueStoreWalConfig.builder()
				.walDirectory(walDirectory)
				.storeUuid("bounded-memory-test")
				.build();
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			if (reader.iterator().hasNext() || reader.isComplete()) {
				throw new AssertionError("A corrupt oversized WAL frame must not be accepted");
			}
		}
	}

	private static String label(int id) {
		return LABEL_PREFIX + id;
	}

	private static void writeFrame(OutputStream output, String json) throws IOException {
		byte[] bytes = json.getBytes(StandardCharsets.UTF_8);
		CRC32C crc = new CRC32C();
		crc.update(bytes, 0, bytes.length);
		writeIntLE(output, bytes.length);
		output.write(bytes);
		writeIntLE(output, (int) crc.getValue());
	}

	private static void writeIntLE(OutputStream output, int value) throws IOException {
		output.write(value);
		output.write(value >>> 8);
		output.write(value >>> 16);
		output.write(value >>> 24);
	}
}
